-- =============================================================
-- Seed: 150 Sales + Sale Lines
-- Schema: sales service (no cross-schema FK — customer_id and
--         sales_point_id are logical references only)
--
-- Design goals:
--   · 150 sales spread across 5 sales points
--   · Customers appear in multiple sales points (cross-point history)
--   · sub_total = quantity × unit_price  (always exact)
--   · total_amount = SUM(sale_lines.sub_total) per sale
--   · payment_method: CASH | CARD | TRANSFER | VOUCHER
--   · status: COMPLETED | REFUNDED | PENDING
--   · Dates: Jan–May 2026, realistic hours
--
-- UUID prefix legend
--   Sales        f1NNNNNN-...  (sale #NN)
--   Sale lines   f2NNNNNN-...  (line within sale)
--   Customers    c1000000-0000-0000-0000-0000000000NN
--   Sales points a1000000-0000-0000-0000-00000000000N
--   Products     b1000000-0000-0000-0000-0000000000NN
-- =============================================================

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- -------------------------------------------------------------
-- SALES  (150 rows)
-- -------------------------------------------------------------
